package io.neo.omnitrix;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

/** Omnitrix Suit v4.7 Wave 2. Forms review/choices + managed Chat channels/threads. */
public class SuiteWave2Activity extends Activity {
 public static final String EXTRA_ID="id",EXTRA_NAME="name";private String id,name,activeFileId;private LinearLayout body;
 @Override public void onCreate(Bundle s){super.onCreate(s);id=getIntent().getStringExtra(EXTRA_ID);name=getIntent().getStringExtra(EXTRA_NAME);activeFileId=getIntent().getStringExtra("file_id");if(id==null)id="";if(name==null)name="Omnitrix App";getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);build();}
 private void build(){LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(Color.rgb(1,5,3));ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(22),dp(18),dp(22));scroll.addView(body);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.omnitrix_logo);body.addView(logo,new LinearLayout.LayoutParams(dp(72),dp(72)));body.addView(text(name,24,Color.rgb(228,255,235)));body.addView(text("Omnitrix Suit v4.7 · BETA",11,Color.rgb(116,255,151)));TextView note=text("Forms choices/responses and Chat channel/thread state remain structured JSON inside the revisioned NEO Cloud E2EE boundary.",11,Color.rgb(142,182,154));note.setPadding(0,dp(8),0,dp(16));body.addView(note);render();shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));shell.addView(OmnitrixNav.bar(this,"NEO"),new LinearLayout.LayoutParams(-1,dp(54)));setContentView(shell);}
 private void render(){switch(id){case "neotube":searchModule("Search and watch video across the open web.","Search videos","video");break;case "neotube-music":mediaOpen("Choose audio from this device or search the web.","audio/*","music");break;case "neotube-tv":searchModule("Discover live TV and public streaming sources.","Search live TV","live tv");break;case "noogle-photos":mediaOpen("Open photos from this device using Android's secure document picker.","image/*","photos");break;case "noogle-podcasts":searchModule("Find podcast episodes and feeds.","Search podcasts","podcast");break;case "noogle-books":searchModule("Search books, previews and public-domain libraries.","Search books","books");break;case "noogle-meet":meet();break;case "noogle-chat":chatWorkspace();break;case "noogle-forms":formWorkspace();break;case "noogle-earth":geo("Explore a place","geo:0,0?q=");break;case "noogle-flights":searchModule("Search flight routes and fares across public travel sources.","Search flights","flights");break;case "noogle-lens":lens();break;default:body.addView(text("This Wave 2 module is registered but has no handler yet.",14,Color.LTGRAY));}}
 private JSONObject currentRecord(){JSONObject rec=activeFileId==null?FileNativeStore.findByApp(this,id):FileNativeStore.find(this,activeFileId);if(rec!=null&&!rec.optBoolean("deleted")){activeFileId=rec.optString("id");return rec;}activeFileId=null;return null;}
 private void formWorkspace(){JSONObject rec=currentRecord();String raw=rec==null?getSharedPreferences("omnitrix_suite",MODE_PRIVATE).getString("wave2_"+id,""):FileNativeStore.body(this,activeFileId);JSONObject form=StructuredWorkspace.form(raw);EditText title=input("Form title");title.setText(rec==null?"Noogle Form":rec.optString("title","Noogle Form"));body.addView(title);EditText desc=input("Description");desc.setText(form.optString("description"));body.addView(desc);JSONArray qs=form.optJSONArray("questions"),rs=form.optJSONArray("responses");body.addView(text("Questions: "+(qs==null?0:qs.length())+" · Responses: "+(rs==null?0:rs.length()),12,Color.rgb(104,185,130)));if(qs!=null)for(int i=0;i<qs.length();i++){JSONObject q=qs.optJSONObject(i);if(q==null)continue;String options="";JSONArray o=q.optJSONArray("options");if(o!=null&&o.length()>0)options=" · "+join(o);body.addView(text((i+1)+". "+q.optString("prompt")+" · "+q.optString("type")+options+(q.optBoolean("required")?" · required":""),12,Color.rgb(205,235,213)));}Button respond=primary("FILL + SUBMIT RESPONSE");body.addView(respond,new LinearLayout.LayoutParams(-1,dp(52)));respond.setOnClickListener(v->{try{form.put("description",desc.getText().toString());}catch(Exception ignored){}openResponseCollector(form,title.getText().toString());});Button review=secondary("REVIEW / EXPORT RESPONSES");body.addView(review,new LinearLayout.LayoutParams(-1,dp(48)));review.setOnClickListener(v->{if(activeFileId==null){Toast.makeText(this,"Save the form first",Toast.LENGTH_SHORT).show();return;}startActivity(new Intent(this,FormResponsesActivity.class).putExtra(FormResponsesActivity.EXTRA_FILE_ID,activeFileId));});EditText prompt=input("New question");body.addView(prompt);Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"text","choice","number","date","email"}));body.addView(type);EditText options=input("Choice options, comma-separated");body.addView(options);CheckBox req=new CheckBox(this);req.setText("Required");req.setTextColor(Color.WHITE);body.addView(req);Button add=secondary("ADD QUESTION");body.addView(add,new LinearLayout.LayoutParams(-1,dp(48)));add.setOnClickListener(v->{String p=prompt.getText().toString().trim();if(p.isEmpty())return;try{form.put("description",desc.getText().toString());}catch(Exception ignored){}StructuredWorkspace.addQuestion(form,p,String.valueOf(type.getSelectedItem()),req.isChecked(),options.getText().toString());saveStructured(title.getText().toString(),form,"Noogle Form");recreate();});Button save=secondary("SAVE FORM + BACKGROUND E2EE SYNC");body.addView(save,new LinearLayout.LayoutParams(-1,dp(50)));save.setOnClickListener(v->{try{form.put("description",desc.getText().toString());}catch(Exception ignored){}saveStructured(title.getText().toString(),form,"Noogle Form");});workspaceButton();}
 private void openResponseCollector(JSONObject form,String requestedTitle){JSONArray qs=form.optJSONArray("questions");if(qs==null||qs.length()==0){Toast.makeText(this,"Add at least one question first",Toast.LENGTH_SHORT).show();return;}LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(8),dp(18),dp(8));ArrayList<JSONObject> defs=new ArrayList<>();ArrayList<View> fields=new ArrayList<>();for(int i=0;i<qs.length();i++){JSONObject q=qs.optJSONObject(i);if(q==null)continue;defs.add(q);box.addView(text(q.optString("prompt")+(q.optBoolean("required")?" *":""),13,Color.DKGRAY));if("choice".equals(q.optString("type"))&&q.optJSONArray("options")!=null&&q.optJSONArray("options").length()>0){JSONArray opts=q.optJSONArray("options");String[] rows=new String[opts.length()];for(int x=0;x<opts.length();x++)rows[x]=opts.optString(x);Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,rows));box.addView(sp);fields.add(sp);}else{EditText e=new EditText(this);e.setHint(q.optString("type","text"));box.addView(e);fields.add(e);}}ScrollView sv=new ScrollView(this);sv.addView(box);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Submit form response").setView(sv).setPositiveButton("SUBMIT",null).setNegativeButton("Cancel",null).create();dlg.setOnShowListener(x->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{JSONObject answers=new JSONObject();for(int i=0;i<defs.size();i++){JSONObject q=defs.get(i);View field=fields.get(i);String val=field instanceof Spinner?String.valueOf(((Spinner)field).getSelectedItem()):((EditText)field).getText().toString().trim();if(q.optBoolean("required")&&val.isEmpty()){Toast.makeText(this,"Required: "+q.optString("prompt"),Toast.LENGTH_SHORT).show();return;}try{answers.put(q.optString("id","q"+i),val);}catch(Exception ignored){}}StructuredWorkspace.addResponse(form,answers);saveStructured(requestedTitle,form,"Noogle Form");dlg.dismiss();recreate();}));dlg.show();}
 private void chatWorkspace(){JSONObject rec=currentRecord();String raw=rec==null?getSharedPreferences("omnitrix_suite",MODE_PRIVATE).getString("wave2_"+id,""):FileNativeStore.body(this,activeFileId);JSONObject chat=StructuredWorkspace.chat(raw);String requestedChannel=getIntent().getStringExtra("channel_id");if(requestedChannel!=null&&!requestedChannel.trim().isEmpty())StructuredWorkspace.setActiveChannel(chat,requestedChannel);String active=chat.optString("activeChannelId");EditText title=input("Chat workspace title");title.setText(rec==null?"Noogle Chat":rec.optString("title","Noogle Chat"));body.addView(title);EditText participants=input("Participants");participants.setText(chat.optString("participants"));body.addView(participants);JSONArray channels=chat.optJSONArray("channels");body.addView(text("CHANNELS",12,Color.rgb(104,185,130)));if(channels!=null)for(int i=0;i<channels.length();i++){JSONObject c=channels.optJSONObject(i);if(c==null)continue;String cid=c.optString("id"),cn=c.optString("name","channel");int unread=StructuredWorkspace.unreadCount(chat,cid,"Local"),mentions=StructuredWorkspace.mentionCount(chat,cid,"Local");String badge=(unread>0?" · "+unread+" unread":"")+(mentions>0?" · @"+mentions:"");Button cb=secondary((cid.equals(active)?"● ":"# ")+cn+badge);body.addView(cb,new LinearLayout.LayoutParams(-1,dp(44)));cb.setOnClickListener(v->{StructuredWorkspace.setActiveChannel(chat,cid);StructuredWorkspace.markChannelRead(chat,cid);try{chat.put("participants",participants.getText().toString());}catch(Exception ignored){}saveStructured(title.getText().toString(),chat,"Noogle Chat");reloadChat(cid);});}EditText newChannel=input("New channel name");body.addView(newChannel);Button addChannel=secondary("CREATE CHANNEL");body.addView(addChannel,new LinearLayout.LayoutParams(-1,dp(46)));addChannel.setOnClickListener(v->{String n=newChannel.getText().toString().trim();if(n.isEmpty())return;String cid=StructuredWorkspace.addChannel(chat,n);try{chat.put("participants",participants.getText().toString());}catch(Exception ignored){}saveStructured(title.getText().toString(),chat,"Noogle Chat");reloadChat(cid);});EditText rename=input("Rename active channel");body.addView(rename);Button renameBtn=secondary("RENAME ACTIVE CHANNEL");body.addView(renameBtn,new LinearLayout.LayoutParams(-1,dp(44)));renameBtn.setOnClickListener(v->{if(StructuredWorkspace.renameChannel(chat,active,rename.getText().toString())){saveStructured(title.getText().toString(),chat,"Noogle Chat");reloadChat(active);}});Button deleteBtn=secondary("DELETE ACTIVE CHANNEL");body.addView(deleteBtn,new LinearLayout.LayoutParams(-1,dp(44)));deleteBtn.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Delete channel?").setMessage("Messages in this channel will be removed from this workspace revision. At least one channel must remain.").setPositiveButton("DELETE",(d,w)->{if(StructuredWorkspace.deleteChannel(chat,active)){saveStructured(title.getText().toString(),chat,"Noogle Chat");reloadChat(chat.optString("activeChannelId"));}else Toast.makeText(this,"Cannot delete the last channel",Toast.LENGTH_SHORT).show();}).setNegativeButton("Cancel",null).show());Button mark=secondary("MARK ACTIVE CHANNEL READ");body.addView(mark,new LinearLayout.LayoutParams(-1,dp(44)));mark.setOnClickListener(v->{StructuredWorkspace.markChannelRead(chat,active);saveStructured(title.getText().toString(),chat,"Noogle Chat");reloadChat(active);});JSONArray msgs=chat.optJSONArray("messages");String channelName=channelName(channels,active);body.addView(text("# "+channelName+" · messages",14,Color.rgb(116,255,151)));if(msgs!=null)for(int i=0;i<msgs.length();i++){JSONObject m=msgs.optJSONObject(i);if(m==null||!active.equals(m.optString("channelId"))||!m.isNull("threadId"))continue;String mid=m.optString("id");body.addView(text(m.optString("author","Local")+": "+m.optString("text"),13,Color.rgb(205,235,213)));int replies=countReplies(msgs,mid,active);Button thread=secondary("OPEN THREAD"+(replies>0?" · "+replies:""));body.addView(thread,new LinearLayout.LayoutParams(-1,dp(40)));thread.setOnClickListener(v->{if(activeFileId==null){Toast.makeText(this,"Save chat first",Toast.LENGTH_SHORT).show();return;}startActivity(new Intent(this,ChatThreadActivity.class).putExtra(ChatThreadActivity.EXTRA_FILE_ID,activeFileId).putExtra(ChatThreadActivity.EXTRA_ROOT_ID,mid));});}EditText author=input("Author");author.setText("Local");body.addView(author);EditText message=input("Message · use @Local for mentions");message.setMinLines(4);message.setGravity(Gravity.TOP);body.addView(message,new LinearLayout.LayoutParams(-1,dp(120)));Button send=primary("SEND MESSAGE + E2EE SYNC");body.addView(send,new LinearLayout.LayoutParams(-1,dp(52)));send.setOnClickListener(v->{String msg=message.getText().toString().trim();if(msg.isEmpty())return;try{chat.put("participants",participants.getText().toString());}catch(Exception ignored){}StructuredWorkspace.addMessage(chat,msg,author.getText().toString(),active,null);saveStructured(title.getText().toString(),chat,"Noogle Chat");reloadChat(active);});Button save=secondary("SAVE CHAT METADATA");body.addView(save,new LinearLayout.LayoutParams(-1,dp(48)));save.setOnClickListener(v->{try{chat.put("participants",participants.getText().toString());}catch(Exception ignored){}saveStructured(title.getText().toString(),chat,"Noogle Chat");});workspaceButton();}
 private String join(JSONArray a){StringBuilder b=new StringBuilder();for(int i=0;i<a.length();i++){if(i>0)b.append(" / ");b.append(a.optString(i));}return b.toString();}
 private String channelName(JSONArray channels,String active){if(channels!=null)for(int i=0;i<channels.length();i++){JSONObject c=channels.optJSONObject(i);if(c!=null&&active.equals(c.optString("id")))return c.optString("name","channel");}return "general";}
 private int countReplies(JSONArray msgs,String root,String channel){int n=0;if(msgs!=null)for(int i=0;i<msgs.length();i++){JSONObject r=msgs.optJSONObject(i);if(r!=null&&channel.equals(r.optString("channelId"))&&root.equals(r.optString("threadId")))n++;}return n;}
 private void reloadChat(String channelId){Intent next=new Intent(this,SuiteWave2Activity.class).putExtra(EXTRA_ID,id).putExtra(EXTRA_NAME,name).putExtra("file_id",activeFileId).putExtra("channel_id",channelId);startActivity(next);finish();}
 private void saveStructured(String requestedTitle,JSONObject data,String fallback){String t=requestedTitle==null?"":requestedTitle.trim();if(t.isEmpty())t=fallback;JSONObject m=activeFileId==null?FileNativeStore.create(this,id,t,StructuredWorkspace.pretty(data),true):FileNativeStore.saveId(this,activeFileId,id,t,StructuredWorkspace.pretty(data),true);activeFileId=m.optString("id");Toast.makeText(this,"Saved rev "+m.optLong("rev")+"; encrypted sync scheduled",Toast.LENGTH_SHORT).show();}
 private void workspaceButton(){Button files=secondary("OPEN / CREATE WORKSPACE");body.addView(files,new LinearLayout.LayoutParams(-1,dp(50)));files.setOnClickListener(v->chooseWorkspace());body.addView(text("Workspace files: "+FileNativeStore.listByApp(this,id,false).length(),11,Color.rgb(104,185,130)));}
 private void chooseWorkspace(){JSONArray a=FileNativeStore.listByApp(this,id,false);String[] rows=new String[a.length()+1];rows[0]="＋ New workspace";for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);rows[i+1]=(m==null?"Workspace":m.optString("title"))+" · rev "+(m==null?0:m.optLong("rev"));}new AlertDialog.Builder(this).setTitle(name+" workspaces").setItems(rows,(d,w)->{Intent next=new Intent(this,SuiteWave2Activity.class).putExtra(EXTRA_ID,id).putExtra(EXTRA_NAME,name);if(w>0){JSONObject m=a.optJSONObject(w-1);if(m!=null)next.putExtra("file_id",m.optString("id"));}startActivity(next);finish();}).setNegativeButton("Cancel",null).show();}
 private void searchModule(String desc,String hint,String suffix){body.addView(text(desc,14,Color.rgb(196,229,204)));EditText q=input(hint);body.addView(q);Button b=primary("SEARCH WITH NOOGLE");body.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->openNoogle(q.getText().toString()+" "+suffix));}
 private void mediaOpen(String desc,String mime,String suffix){body.addView(text(desc,14,Color.rgb(196,229,204)));Button open=primary("OPEN DEVICE MEDIA");body.addView(open,new LinearLayout.LayoutParams(-1,dp(52)));open.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);try{startActivity(i);}catch(Exception e){Toast.makeText(this,"No compatible media picker found",Toast.LENGTH_SHORT).show();}});Button search=secondary("SEARCH "+suffix.toUpperCase());body.addView(search,new LinearLayout.LayoutParams(-1,dp(50)));search.setOnClickListener(v->openNoogle(suffix));}
 private void meet(){body.addView(text("Create or join a meeting through compatible installed conferencing software.",14,Color.rgb(196,229,204)));EditText room=input("Meeting code or URL");body.addView(room);Button open=primary("OPEN MEETING LINK");body.addView(open,new LinearLayout.LayoutParams(-1,dp(52)));open.setOnClickListener(v->{String s=room.getText().toString().trim();if(s.isEmpty())return;Uri u=Uri.parse(s.contains("://")?s:"https://"+s);try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"No meeting handler found",Toast.LENGTH_SHORT).show();}});}
 private void geo(String hint,String base){body.addView(text("Noogle Earth beta hands place queries to an installed geo provider, with Noogle search fallback.",14,Color.rgb(196,229,204)));EditText q=input(hint);body.addView(q);Button b=primary("EXPLORE");body.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));b.setOnClickListener(v->{String s=q.getText().toString().trim();if(s.isEmpty())return;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(base+Uri.encode(s))));}catch(Exception e){openNoogle(s+" map earth");}});}
 private void lens(){body.addView(text("Noogle Lens beta launches the device camera; production visual recognition remains adapter-only.",14,Color.rgb(196,229,204)));Button camera=primary("OPEN CAMERA");body.addView(camera,new LinearLayout.LayoutParams(-1,dp(52)));camera.setOnClickListener(v->{Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);try{startActivity(i);}catch(Exception e){Toast.makeText(this,"Camera unavailable",Toast.LENGTH_SHORT).show();}});Button pick=secondary("CHOOSE IMAGE");body.addView(pick,new LinearLayout.LayoutParams(-1,dp(50)));pick.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivity(i);});}
 private void openNoogle(String q){Intent i=new Intent(this,NoogleBrowserActivity.class);i.putExtra(NoogleBrowserActivity.EXTRA_QUERY,q==null?"":q.trim());startActivity(i);}
 private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(Color.WHITE);e.setHintTextColor(Color.rgb(102,132,112));e.setBackgroundColor(Color.rgb(5,20,12));e.setPadding(dp(12),dp(10),dp(12),dp(10));return e;}
 private TextView text(String s,float z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}private Button primary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.rgb(0,22,8));b.setBackgroundColor(Color.rgb(101,255,138));return b;}private Button secondary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.rgb(190,235,202));b.setBackgroundColor(Color.rgb(7,25,15));return b;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
